/* Shared locale and route registry. Keep route availability explicit: /en is not a fallback rule. */
(() => {
  const DEFAULT_LOCALE = "es";
  const SUPPORTED_LOCALES = Object.freeze(["es", "en"]);
  const ROUTES = Object.freeze({
    home: Object.freeze({ es: "/index.html", en: "/en/index.html" }),
    "maps.nano.product": Object.freeze({ es: "/product_maps_nano.html", en: "/en/product_maps_nano.html" }),
    "maps.nano.pricing": Object.freeze({ es: "/map-nano-pricing.html", en: "/en/map-nano-pricing.html" }),
    "workspace.client": Object.freeze({ es: "/dashboard.html", en: "/en/dashboard.html" }),
    "workspace.staff": Object.freeze({ es: "/staff-dashboard.html", en: "/en/staff-dashboard.html" })
  });

  const normalizeLocale = value => String(value || "").toLowerCase().startsWith("en") ? "en" : DEFAULT_LOCALE;
  const locale = () => normalizeLocale(document.documentElement.lang || (location.pathname.startsWith("/en/") ? "en" : DEFAULT_LOCALE));
  const route = (id, requestedLocale = locale()) => ROUTES[id]?.[normalizeLocale(requestedLocale)] || null;

  function routeForPath(pathname = location.pathname, requestedLocale = locale()) {
    const normalizedPath = String(pathname || "/").replace(/\/+$/, "") || "/";
    const entry = Object.values(ROUTES).find(routes => Object.values(routes).some(value => value === normalizedPath || value === `${normalizedPath}.html`));
    return entry?.[normalizeLocale(requestedLocale)] || null;
  }

  function workspaceRouteForUser(user, requestedLocale = locale()) {
    const isStaff = Boolean(user?.permissions?.includes("admin:view") || user?.permissions?.includes("staff:view") || ["staff", "admin"].includes(user?.role));
    return route(isStaff ? "workspace.staff" : "workspace.client", requestedLocale);
  }

  window.BCCI18n = Object.freeze({
    DEFAULT_LOCALE,
    SUPPORTED_LOCALES,
    routes: ROUTES,
    normalizeLocale,
    locale,
    route,
    routeForPath,
    workspaceRouteForUser
  });
})();

/* Source: js/prefs.js */
/* BCC Technologies - Preferences (theme + language) */
(() => {
  const THEME_KEY = 'bcc-theme';
  const LANG_KEY = 'bcc-lang';

  function getSaved(key) {
    try { return localStorage.getItem(key); } catch { return null; }
  }

  function setSaved(key, value) {
    try { localStorage.setItem(key, value); } catch {}
  }

  function normalizeLang(raw) {
    if (!raw) return 'es';
    const lower = String(raw).toLowerCase();
    return lower.startsWith('en') ? 'en' : 'es';
  }

  function getSavedLang() {
    const saved = getSaved(LANG_KEY);
    return saved === 'en' || saved === 'es' ? saved : null;
  }

  function detectBrowserLang() {
    const list = (navigator.languages && navigator.languages.length)
      ? navigator.languages
      : [navigator.language || ''];
    for (const entry of list) {
      const norm = normalizeLang(entry);
      if (norm === 'en' || norm === 'es') return norm;
    }
    return 'es';
  }

  function getPathLang() {
    return window.location.pathname.toLowerCase().startsWith('/en/') ? 'en' : 'es';
  }

  function mapPathToLang(pathname, lang) {
    const explicitRoute = window.BCCI18n?.routeForPath?.(pathname, lang);
    if (explicitRoute) return explicitRoute;
    const path = pathname || '/';
    if (lang === 'en') {
      if (path.toLowerCase().startsWith('/en/')) return path;
      if (path === '/' || path === '') return '/en/index.html';
      return '/en' + (path.startsWith('/') ? path : '/' + path);
    }
    if (path.toLowerCase().startsWith('/en/')) {
      const stripped = path.slice(3);
      if (stripped === '/' || stripped === '') return '/index.html';
      return stripped;
    }
    return path;
  }

  function getAlternateHref(lang) {
    const link = document.querySelector(`link[rel="alternate"][hreflang="${lang}"]`);
    if (!link) return null;
    const href = link.getAttribute('href');
    if (!href) return null;
    return new URL(href, window.location.href).pathname;
  }

  function getSwitchHref(lang) {
    const link = document.querySelector('a.lang-switch[href]');
    if (!link) return null;
    const href = link.getAttribute('href');
    if (!href) return null;
    const targetLang = href.includes('/en/') ? 'en' : 'es';
    if (targetLang !== lang) return null;
    return new URL(href, window.location.href).pathname;
  }

  function getLangTargets() {
    const meta = document.querySelector('meta[name="bcc-lang-targets"]');
    if (!meta) return null;
    const content = (meta.getAttribute('content') || '').toLowerCase();
    const list = content.split(',').map(x => normalizeLang(x.trim())).filter(Boolean);
    return list.length ? Array.from(new Set(list)) : null;
  }

  function resolveLangTarget(lang) {
    return getAlternateHref(lang) || getSwitchHref(lang) || window.BCCI18n?.routeForPath?.(window.location.pathname, lang) || mapPathToLang(window.location.pathname, lang);
  }

  function languageSwitchTarget(lang) {
    const targetPath = resolveLangTarget(lang);
    return targetPath ? `${targetPath}${window.location.search}${window.location.hash}` : null;
  }

  function isAutoLangLanding() {
    const path = window.location.pathname.toLowerCase();
    return path === '/' || path === '/index.html' || path === '/en/' || path === '/en/index.html';
  }

  function maybeRedirectLang() {
    const saved = getSavedLang();
    const desired = saved || detectBrowserLang();
    const current = getPathLang();
    const targets = getLangTargets();
    if (targets && !targets.includes(desired)) return;
    if (desired === current) return;
    if (!saved && !isAutoLangLanding()) return;
    const targetPath = resolveLangTarget(desired);
    if (!targetPath || targetPath === window.location.pathname) return;
    const next = languageSwitchTarget(desired);
    window.location.replace(next);
  }

  function getCurrentTheme() {
    const data = document.documentElement.dataset.theme;
    if (data === 'dark' || data === 'light') return data;
    const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    return prefersDark ? 'dark' : 'light';
  }

  function applyTheme(theme, persist) {
    const safe = theme === 'dark' ? 'dark' : 'light';
    document.documentElement.dataset.theme = safe;
    updateThemeButtons(safe);
    if (persist) setSaved(THEME_KEY, safe);
  }

  function updateThemeButtons(theme) {
    const lang = document.documentElement.lang && document.documentElement.lang.toLowerCase().startsWith('en') ? 'en' : 'es';
    const aria = theme === 'dark'
      ? (lang === 'en' ? 'Switch to light mode' : 'Cambiar a modo claro')
      : (lang === 'en' ? 'Switch to dark mode' : 'Cambiar a modo oscuro');
    document.querySelectorAll('[data-action="toggle-theme"]').forEach((btn) => {
      btn.setAttribute('aria-label', aria);
      btn.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
    });
  }

  function updateLanguageSwitches() {
    const current = getPathLang();
    const target = current === 'en' ? 'es' : 'en';
    const targetHref = languageSwitchTarget(target);
    const label = target === 'en'
      ? 'Cambiar a inglés'
      : 'Switch to Spanish';
    document.querySelectorAll('[data-language-switch]').forEach((switcher) => {
      if (!targetHref) {
        switcher.hidden = true;
        return;
      }
      switcher.hidden = false;
      switcher.setAttribute('href', targetHref);
      switcher.setAttribute('aria-label', label);
      switcher.setAttribute('title', label);
      const text = switcher.querySelector('span') || switcher;
      text.textContent = target.toUpperCase();
    });
  }

  function init() {
    const savedTheme = getSaved(THEME_KEY);
    if (savedTheme === 'dark' || savedTheme === 'light') {
      document.documentElement.dataset.theme = savedTheme;
    }
    updateThemeButtons(getCurrentTheme());
    updateLanguageSwitches();

    document.querySelectorAll('[data-action="toggle-theme"]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const current = getCurrentTheme();
        applyTheme(current === 'dark' ? 'light' : 'dark', true);
      });
    });

    document.querySelectorAll('a.lang-switch, button.lang-switch').forEach((el) => {
      el.addEventListener('click', (event) => {
        const href = el.getAttribute('href') || '';
        const targetLang = href.includes('/en/') ? 'en' : 'es';
        setSaved(LANG_KEY, targetLang);
        if (!el.hasAttribute('data-language-switch')) return;
        const next = languageSwitchTarget(targetLang);
        if (!next) return;
        event.preventDefault();
        window.location.assign(next);
      });
    });

    window.addEventListener('bcc:workspace-route-change', updateLanguageSwitches);
    window.addEventListener('hashchange', updateLanguageSwitches);
  }

  maybeRedirectLang();
  document.addEventListener('DOMContentLoaded', init);
})();

/* Source: js/supabase-config.js */
(() => {
  const config = {
    url: "https://bglkyqiqzrcwegpjrucc.supabase.co",
    anonKey: "sb_publishable_X_3U_TNtC9BuVwc-vMCsug_GVFmI5cQ"
  };
  const localHostnames = new Set(["localhost", "127.0.0.1", "::1"]);
  const runtime = Object.freeze({
    isLocal: localHostnames.has(window.location.hostname),
    allowLocalAccountFallback: localHostnames.has(window.location.hostname)
  });
  let libraryPromise = null;
  let clientPromise = null;

  function loadLibrary() {
    if (window.supabase?.createClient) return Promise.resolve(window.supabase);
    if (libraryPromise) return libraryPromise;

    libraryPromise = new Promise((resolve, reject) => {
      const selector = 'script[data-bcc-supabase-js="true"], script[data-supabase-js]';
      const existing = document.querySelector(selector);
      const onLoad = () => window.supabase?.createClient
        ? resolve(window.supabase)
        : reject(new Error("Supabase JS cargó sin exponer createClient."));
      const onError = () => reject(new Error("No se pudo cargar Supabase JS."));

      if (existing) {
        existing.addEventListener("load", onLoad, { once: true });
        existing.addEventListener("error", onError, { once: true });
        return;
      }

      const script = document.createElement("script");
      script.src = "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.110.8";
      script.async = true;
      script.dataset.bccSupabaseJs = "true";
      script.onload = onLoad;
      script.onerror = onError;
      document.head.appendChild(script);
    }).catch(error => {
      libraryPromise = null;
      throw error;
    });
    return libraryPromise;
  }

  function getClient() {
    if (window.BCCSupabaseClient) return Promise.resolve(window.BCCSupabaseClient);
    if (clientPromise) return clientPromise;
    clientPromise = loadLibrary().then(supabaseJs => {
      window.BCCSupabaseClient = supabaseJs.createClient(config.url, config.anonKey, {
        auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true }
      });
      return window.BCCSupabaseClient;
    }).catch(error => {
      clientPromise = null;
      throw error;
    });
    return clientPromise;
  }

  function classifyError(error) {
    const code = String(error?.code || error?.name || "").toLowerCase();
    const message = String(error?.message || error || "").toLowerCase();
    const status = Number(error?.status || error?.statusCode || 0);
    if (code === "authsessionmissingerror" || code === "auth_session_missing") return "auth_session_missing";
    if (code.includes("refresh_token") || message.includes("refresh token")) return "auth_refresh_invalid";
    if (message.includes("jwt expired") || message.includes("invalid jwt") || message.includes("token is expired")) return "auth_session_invalid";
    if (status === 401 || code.includes("invalid_credentials")) return "auth_invalid_credentials";
    if (status === 403 || code === "42501" || code === "pgrst301") return "permission_denied";
    if (status === 404 || code === "pgrst116") return "not_found";
    if (code === "pgrst204" || code === "42703") return "schema_mismatch";
    if (status >= 500) return "server";
    if (error instanceof TypeError || message.includes("failed to fetch") || message.includes("network")) return "network";
    return "unknown";
  }

  function normalizeError(error, context = "Operación de Supabase") {
    const category = classifyError(error);
    const messages = {
      auth_invalid_credentials: "El correo o la contraseña no son correctos.",
      permission_denied: "No tienes permiso para realizar esta acción.",
      network: "No fue posible conectar con el servicio. Revisa tu conexión e inténtalo de nuevo.",
      server: "El servicio no está disponible temporalmente. Inténtalo de nuevo.",
      schema_mismatch: "La aplicación y la base de datos no están sincronizadas.",
      not_found: "No se encontró la información solicitada.",
      auth_refresh_invalid: "Tu sesión venció. Inicia sesión nuevamente.",
      auth_session_missing: "No hay una sesión activa.",
      auth_session_invalid: "No se pudo validar la sesión actual. Inténtalo de nuevo.",
      unknown: "No fue posible completar la operación."
    };
    return { category, code: String(error?.code || error?.name || "supabase_error"), status: Number(error?.status || error?.statusCode || 0) || null, context, userMessage: messages[category], cause: error };
  }

  function reportError(context, error) {
    const normalized = normalizeError(error, context);
    if (normalized.category !== "auth_session_missing") {
      console.warn("[Supabase]", { context: normalized.context, category: normalized.category, code: normalized.code, status: normalized.status });
    }
    if (typeof window.CustomEvent === "function") window.dispatchEvent?.(new window.CustomEvent("bcc:supabase-error", { detail: { ...normalized, cause: undefined } }));
    return normalized;
  }

  window.BCC_SUPABASE = config;
  window.BCC_RUNTIME = runtime;
  window.BCCSupabase = { loadLibrary, getClient };
  window.BCCSupabaseErrors = { classify: classifyError, normalize: normalizeError, report: reportError };
})();

